#!/usr/bin/env python3
"""Build a self-contained, curated progress page. Does not infer verification."""
import csv
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / 'context/16_agent_research'
esc = lambda x: html.escape(str(x), quote=True)


def build():
    status = json.loads((BASE / 'status.json').read_text())
    notes = json.loads((BASE / 'journal_notes.json').read_text())
    wishlist = list(csv.DictReader((BASE / 'data_wishlist.csv').open()))
    roles = ''.join(f'<article><h3>{esc(r["title"])}</h3><p class="meta">{esc(r["model"])}</p><p>{esc(r["work"])}</p><p class="state">{esc(r["result"])}</p>' + (f'<a href="https://github.com/Mput13/case_championship/tree/{esc(r["branch"])}">Исследовательская ветка</a>' if r.get('branch') and r.get('pushed_sha') else '') + '</article>' for r in notes['roles'])
    received = ''.join(f'<tr><td data-label="Набор">{esc(r["name"])}</td><td data-label="Охват">{esc(r["coverage"])}</td><td data-label="Что проверено">{esc(r["checked"])}</td><td data-label="Ограничение">{esc(r["limit"])}</td></tr>' for r in notes['received'])
    rows = ''
    for r in wishlist:
        search = esc(' '.join(r.values()).lower())
        rows += f'''<details class="dataset" data-search="{search}" data-track="{esc(r['track'])}"><summary><span class="code">{esc(r['id'])}</span> {esc(r['dataset'])}</summary><dl><dt>Для решения</dt><dd>{esc(r['decision_use'])}</dd><dt>Нужные поля</dt><dd>{esc(r['wanted_fields'])}</dd><dt>Единица наблюдения</dt><dd>{esc(r['grain'])}</dd><dt>Ключи объединения</dt><dd>{esc(r['join_keys'])}</dd><dt>Где искать</dt><dd>{esc(r['candidate_sources_not_verified'])}</dd><dt>Главный риск</dt><dd>{esc(r['main_failure_mode'])}</dd></dl></details>'''
    updates = ''.join(f'<li><strong>{esc(r["title"])}</strong><p>{esc(r["text"])}</p></li>' for r in notes['colleagues'])
    checkpoints = ''.join(f'<li><strong>{esc(r["time"])}</strong> — {esc(r["work"])}</li>' for r in notes['checkpoints'])
    experiments = ''.join(f'<li><strong>{esc(r["title"])}</strong><p>{esc(r["text"])}</p></li>' for r in notes.get('next_experiments', []))
    content = '''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Red Wings — журнал исследования данных</title><style>
    *{box-sizing:border-box}body{margin:0;color:var(--foreground,#192c39);font:16px/1.6 var(--font-sans,system-ui,sans-serif)}main{max-width:1120px;margin:0 auto}header{padding:20px 16px 10px;border-bottom:1px solid var(--border,#d8e0e5)}h1{font-size:clamp(25px,4vw,36px);line-height:1.2;letter-spacing:-.025em;margin:8px 0 14px}h2{font-size:23px;line-height:1.3;margin:0 0 16px}h3{font-size:17px;line-height:1.4;margin:0 0 5px}p{margin:10px 0}.meta{font-size:14px;color:var(--muted-foreground,#596b76)}nav{display:flex;flex-wrap:wrap;gap:8px 20px;margin:18px 0}a{color:var(--primary,#245ba7);text-underline-offset:3px}section{padding:28px 16px;border-bottom:1px solid var(--border,#d8e0e5);scroll-margin-top:12px}.roles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}article{padding:16px;background:var(--card,#f3f6f7);border:1px solid var(--border,#d8e0e5);border-radius:var(--radius,8px)}.state{font-size:14px;border-top:1px solid var(--border,#d8e0e5);padding-top:9px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid var(--border,#d8e0e5);min-width:160px}th{font-weight:600;background:var(--secondary,#eef3f5)}td:first-child{min-width:180px;font-weight:600}.flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.flow div{padding:12px;border-left:3px solid var(--primary,#245ba7);background:var(--card,#f3f6f7)}.flow small{display:block;color:var(--muted-foreground,#596b76);line-height:1.5;margin-top:5px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}label{display:flex;align-items:center;gap:9px;flex:1}input,select{font:inherit;padding:9px 12px;max-width:100%;min-width:0;border:1px solid var(--border,#c4d0d8);border-radius:6px;background:var(--background,white);color:inherit}input{flex:1;width:100%}:focus-visible{outline:3px solid var(--ring,#6b9ad5);outline-offset:2px}details{border-top:1px solid var(--border,#d8e0e5);padding:11px 0}summary{cursor:pointer;font-weight:600}.code{font:13px var(--font-mono,monospace);color:var(--muted-foreground,#596b76);margin:0 7px}.dataset dl{display:grid;grid-template-columns:180px minmax(0,1fr);gap:8px 18px;padding:0 12px}dt{font-weight:600}dd{margin:0;overflow-wrap:anywhere}li{margin-bottom:12px}li p{margin:5px 0}.empty{display:none}footer{padding:24px 16px;color:var(--muted-foreground,#596b76);font-size:14px}@media(max-width:600px){.roles,.flow{grid-template-columns:1fr}.dataset dl{grid-template-columns:1fr;gap:3px}dd{margin-bottom:9px}section{padding:24px 16px}label{flex-basis:100%}.controls select{width:100%}}
    @media(max-width:600px){.scroll{overflow:visible}table,tbody,tr,td{display:block;width:100%;min-width:0!important}thead{display:none}tr{margin:0 0 18px;border:1px solid var(--border,#d8e0e5);border-radius:8px}td{border:0;padding:9px 14px}td:before{content:attr(data-label);display:block;font-size:12px;color:var(--muted-foreground,#596b76);font-weight:600}td:first-child{font-size:16px}}
    </style></head><body><main><header><div class="meta">Исследование Red Wings · срез {{TIME}} МСК</div><h1>Данные, проверки и гипотезы</h1><p>{{LEAD}}</p><nav><a href="https://red-wings-case-team-20261109.dear-bell-1406.chatgpt.site/research/report.html">Подробный отчёт</a><a href="#work">Кто чем занят</a><a href="#received">Полученные данные</a><a href="#wishlist">Что ищем</a><a href="#colleagues">Обновления коллег</a><a href="#decisions">Твой следующий выбор</a></nav></header>
    <section id="work"><h2>Работа агентов</h2><div class="roles">{{ROLES}}</div><p class="meta">Статусы отражают последний проверенный срез. Эта страница обновляется при проверках координатора; между ними данные могут появляться в рабочих папках.</p></section>
    <section id="received"><h2>Что уже получено</h2><div class="scroll"><table><thead><tr><th>Набор</th><th>Охват</th><th>Что проверено</th><th>Чего из него не следует</th></tr></thead><tbody>{{RECEIVED}}</tbody></table></div><p>Хеш подтверждает сохранность файла. Он не подтверждает точность каждого значения или пригодность показателя для прогноза спроса.</p><p>{{UNKNOWN}}</p></section>
    <section id="loop"><h2>Как будем оценивать</h2><div class="flow"><div><strong>1. Наблюдения</strong><small>Источник, дата, единица, география; пропуск остаётся пропуском.</small></div><div><strong>2. Кандидат сети</strong><small>Кто летит, куда и почему; расписание, ресурс и конкурент.</small></div><div><strong>3. Расчёт кодом</strong><small>Кресла, поездки, деньги, каннибализация, ограничения и сценарии.</small></div><div><strong>4. Проверка</strong><small>Что выдержало критику; какой факт изменит выбор; следующий опыт.</small></div></div><p>Общие показатели позволяют сравнивать варианты. Особенности города, сезона и пассажира входят отдельными проверяемыми модулями. Генератор гипотез не меняет веса или неизвестный спрос ради победы своего варианта.</p><p>Пока нет калиброванного спроса и договорной экономики, полезный результат — условия окупаемости и смены решения, вместе с данными за и против их достижимости. Городской балл не равен вероятности успеха.</p></section>
    <section id="wishlist"><h2>Перечень желательных данных</h2><p>30 групп. Указанные источники — направления поиска; доступность и полнота каждого ещё проверяются. Искать будем шире текущего шортлиста.</p><div class="controls"><label for="search">Поиск<input id="search" type="search" placeholder="Например, миграция или конкуренты"></label><select id="track" aria-label="Группа данных"><option value="">Все группы</option><option value="core">Основные</option><option value="alternative">Дополнительные</option><option value="validation">Проверка</option></select></div><p id="shown" class="meta" aria-live="polite"></p>{{WISHLIST}}<p id="empty" class="empty">По этому запросу групп нет.</p></section>
    <section id="colleagues"><h2>Новые материалы коллег</h2><ul>{{UPDATES}}</ul><p>Новые коммиты передаются исследователям с закреплённой версией. Изменившийся результат расчёта требует проверки исходных допущений; статус «нашли обновление» не равен «приняли вывод».</p></section>
    <section id="decisions"><h2>Твой следующий выбор</h2><p>Сейчас вручную проверять таблицы и назначать отраслевые коэффициенты не нужно. После первого среза покажем несколько различающихся направлений работы: какой пассажир и проблема стоят за ними, на каких данных они держатся, что остаётся предположением и какой опыт стоит провести первым.</p><p>С тебя — приоритеты, допустимые компромиссы и выбор вариантов для углубления. С агентов — воспроизводимый расчёт, проверка данных и понятное объяснение ограничений.</p><ul>{{CHECKPOINTS}}</ul></section><footer><a href="https://red-wings-case-team-20261109.dear-bell-1406.chatgpt.site">Общая объяснялка команды</a> · Россия — основной охват. Международные аналоги рассматриваются отдельно.</footer></main><script>
    const search=document.getElementById('search'),track=document.getElementById('track'),items=[...document.querySelectorAll('.dataset')];function filter(){const q=search.value.trim().toLowerCase();let n=0;for(const item of items){const ok=(!track.value||item.dataset.track===track.value)&&item.dataset.search.includes(q);item.hidden=!ok;if(ok)n++;}document.getElementById('shown').textContent=`Показано ${n} из ${items.length}`;document.getElementById('empty').style.display=n?'none':'block';}search.addEventListener('input',filter);track.addEventListener('change',filter);filter();
    </script></body></html>'''
    for key, value in {'TIME': esc(notes['updated_msk']), 'LEAD': esc(notes['lead']),
                       'ROLES': roles, 'RECEIVED': received, 'WISHLIST': rows,
                       'UNKNOWN': esc(notes['unknown']), 'UPDATES': updates,
                       'CHECKPOINTS': checkpoints}.items():
        content = content.replace('{{' + key + '}}', value)
    content = content.replace('<section id="decisions">', '<section id="experiments"><h2>Ближайшие проверки</h2><ul>' + experiments + '</ul></section><section id="decisions">')
    output = ROOT / 'research-board.html'
    output.write_text(content)
    print(f'{output}: {len(wishlist)} data groups, {len(notes["received"])} received summaries')


if __name__ == '__main__':
    build()
